import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/11-Implementation_Plan.html","title":"Apollo MMORPG 服务器实施计划","lang":"en-US","frontmatter":{},"filePathRelative":"11-Implementation_Plan.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`11-Implementation_Plan.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="apollo-mmorpg-服务器实施计划" tabindex="-1"><a class="header-anchor" href="#apollo-mmorpg-服务器实施计划"><span>Apollo MMORPG 服务器实施计划</span></a></h1><blockquote><p><strong>版本</strong>: 2.0<br><strong>更新日期</strong>: 2024-12-07<br><strong>项目周期</strong>: 12 个月<br><strong>团队规模</strong>: 10-14 人</p></blockquote><h2 id="_1-项目目标" tabindex="-1"><a class="header-anchor" href="#_1-项目目标"><span>1. 项目目标</span></a></h2><h3 id="_1-1-核心指标" tabindex="-1"><a class="header-anchor" href="#_1-1-核心指标"><span>1.1 核心指标</span></a></h3><ol><li><strong>性能</strong>：单服 5000+ CCU，核心操作 P99 &lt; 60 ms，吞吐线性扩展。</li><li><strong>可用性</strong>：99.95% 年可用性，具备弹性扩容、自动化运维能力。</li><li><strong>易扩展</strong>：模块化架构（NetCore、AOI、DataProxy、插件系统），支持新玩法快速接入。</li><li><strong>安全与 SDK</strong>：提供 Unity SDK、GM/运营 API，具备 TLS/mTLS、RBAC、审计。</li></ol><h3 id="_1-2-验收标准" tabindex="-1"><a class="header-anchor" href="#_1-2-验收标准"><span>1.2 验收标准</span></a></h3><ul><li>[ ] NetCore + Unity SDK 在测试环境跑通 5k 虚拟客户端压测。</li><li>[ ] AOI/Scene/Battle 服务具备独立扩缩、故障隔离能力。</li><li>[ ] DataProxy 与 TLog 体系稳定运行，BI 可实时查询核心指标。</li><li>[ ] DevOps/监控/安全体系上线，发布流程可灰度与回滚。</li></ul><h2 id="_2-团队组织" tabindex="-1"><a class="header-anchor" href="#_2-团队组织"><span>2. 团队组织</span></a></h2><table><thead><tr><th>角色</th><th>人数</th><th>主要职责</th></tr></thead><tbody><tr><td>架构师</td><td>1</td><td>总体架构、关键模块把控</td></tr><tr><td>网络/基础设施工程师</td><td>2</td><td>NetCore、Transport、SDK</td></tr><tr><td>服务器逻辑工程师</td><td>4</td><td>Gate/Zone/AOI/Battle/业务模块</td></tr><tr><td>数据/平台工程师</td><td>2</td><td>DataProxy、数据库、BI/TLog</td></tr><tr><td>运维/DevOps</td><td>2</td><td>CI/CD、监控、发布、安全</td></tr><tr><td>QA/测试</td><td>2</td><td>自动化测试、压测、SDK 联调</td></tr><tr><td>产品/项目</td><td>1</td><td>需求、排期、跨团队协调</td></tr></tbody></table><p>协作方式：Scrum + 2 周迭代，每个阶段设立里程碑评审；关键模块需要设计评审 + 安全评审。</p><h2 id="_3-阶段规划" tabindex="-1"><a class="header-anchor" href="#_3-阶段规划"><span>3. 阶段规划</span></a></h2><h3 id="phase-1-基础架构搭建-2025-01-2025-03" tabindex="-1"><a class="header-anchor" href="#phase-1-基础架构搭建-2025-01-2025-03"><span>Phase 1：基础架构搭建 (2025.01 - 2025.03)</span></a></h3><table><thead><tr><th>模块</th><th>负责人</th><th>任务要点</th><th>产出</th></tr></thead><tbody><tr><td>NetCore &amp; SDK</td><td>架构师 + 网络工程师</td><td>- 基于 io_uring/IOCP 的 NetCore 实现<br>- 消息格式/握手/去重/限流<br>- Unity SDK (C#) 初版</td><td>NetCore 源码、SDK 包、<code>docs/16</code> 更新</td></tr><tr><td>Transport 层</td><td>网络工程师</td><td>- 实现 NNG TCP/IPC Transport<br>- ServiceRegistry 集成，动态选择 transport</td><td>Transport 库、<code>docs/13</code> 实施</td></tr><tr><td>Spring-like 基础设施</td><td>服务器工程师</td><td>- ApplicationContext 2.0（Bean/依赖/事件）<br>- 配置系统升级、命令行解析、事件/任务调度</td><td><code>common</code> 模块、<code>docs/14</code> 落地</td></tr><tr><td>插件系统</td><td>平台工程师</td><td>- SharedLibrary 封装、插件注册接口<br>- MySQL/Redis 插件 PoC</td><td>插件框架、<code>docs/15</code> 实施</td></tr><tr><td>DevOps 基础</td><td>DevOps 团队</td><td>- CI/CD Pipeline（构建+测试）<br>- Prometheus/Grafana 最小集、日志采集</td><td>CI/CD 配置、<code>docs/20</code> Phase1</td></tr></tbody></table><h3 id="phase-2-核心服务开发-2025-04-2025-07" tabindex="-1"><a class="header-anchor" href="#phase-2-核心服务开发-2025-04-2025-07"><span>Phase 2：核心服务开发 (2025.04 - 2025.07)</span></a></h3><table><thead><tr><th>模块</th><th>负责人</th><th>任务要点</th><th>产出</th></tr></thead><tbody><tr><td>GateServer</td><td>网络 + 服务器工程师</td><td>- 与 NetCore/SDK 对接<br>- 会话管理、限流、防刷、灰度<br>- 监控指标与调试工具</td><td>Gate 模块、压测报告</td></tr><tr><td>Scene Orchestrator &amp; ZoneServer</td><td>服务器工程师</td><td>- 场景生命周期、实例池<br>- Zone ECS/战斗主循环</td><td>实例管理服务、<code>docs/17</code> 实施</td></tr><tr><td>AOI Service</td><td>服务器工程师</td><td>- AOI 分片、事件协议、容灾<br>- 与 Zone/Gate/Transport 集成</td><td>AOI 服务、协议文档</td></tr><tr><td>DataProxy &amp; Hybrid Schema</td><td>数据工程师</td><td>- DataProxy v1（Load/Save/缓存写队列）<br>- Hybrid Schema、分库分表计划<br>- TLog 管线</td><td>DataProxy 服务、<code>docs/18</code> 落地</td></tr><tr><td>API &amp; SDK 标准</td><td>平台 + 网络工程师</td><td>- 重写内部 gRPC/外部 REST 规范<br>- SDK/Proto/OpenAPI 生成工具</td><td><code>docs/19</code> 实施、API Gateway</td></tr><tr><td>安全基线</td><td>DevOps + 安全</td><td>- TLS/mTLS、HMAC、防重放<br>- OAuth2/Keycloak、RBAC、审计</td><td>安全设施、<code>docs/21</code> Phase1</td></tr></tbody></table><h3 id="phase-3-系统强化与玩法-2025-08-2025-10" tabindex="-1"><a class="header-anchor" href="#phase-3-系统强化与玩法-2025-08-2025-10"><span>Phase 3：系统强化与玩法 (2025.08 - 2025.10)</span></a></h3><table><thead><tr><th>模块</th><th>任务</th><th>产出</th></tr></thead><tbody><tr><td>Battle Service &amp; 扩展玩法</td><td>- 大型战斗 offload 服务<br>- 统一技能流水线、状态同步</td><td>Battle Service、压测结果</td></tr><tr><td>Social/Integration</td><td>- Chat/Guild/Match、邮件交易<br>- 与 DataProxy/TLog 一致性检查</td><td>社交模块</td></tr><tr><td>插件扩展</td><td>- Mongo/ClickHouse/其他数据源插件<br>- 共享内存 transport PoC</td><td>新增插件、性能评估</td></tr><tr><td>Observability &amp; Ops</td><td>- 完善日志、追踪、自愈<br>- 压测平台、流量复制</td><td>监控体系完善</td></tr><tr><td>安全进阶</td><td>- 反作弊集成、插件签名、渗透测试</td><td>安全评估报告</td></tr></tbody></table><h3 id="phase-4-稳定化与上线准备-2025-11-2025-12" tabindex="-1"><a class="header-anchor" href="#phase-4-稳定化与上线准备-2025-11-2025-12"><span>Phase 4：稳定化与上线准备 (2025.11 - 2025.12)</span></a></h3><table><thead><tr><th>模块</th><th>任务</th><th>产出</th></tr></thead><tbody><tr><td>全链路压测</td><td>- 客户端压测（5k+并发）<br>- AOI/Zone/Battle 极限场景</td><td>压测报告</td></tr><tr><td>SDK &amp; API 发布</td><td>- Unity SDK 正式版、文档、示例项目<br>- GM/运营 API 上线（含审批流程）</td><td>SDK 交付物、API 门户</td></tr><tr><td>运维与安全演练</td><td>- 故障演练、回滚演练、灾备验证<br>- 安全事件响应演练</td><td>演练报告</td></tr><tr><td>文档与培训</td><td>- 所有设计/运维文档冻结<br>- 培训开发/运维人员</td><td>文档库、培训材料</td></tr></tbody></table><h2 id="_4-关键依赖与风险" tabindex="-1"><a class="header-anchor" href="#_4-关键依赖与风险"><span>4. 关键依赖与风险</span></a></h2><table><thead><tr><th>风险</th><th>描述</th><th>缓解措施</th></tr></thead><tbody><tr><td>NetCore 性能风险</td><td>io_uring/IOCP 实现复杂，可能影响进度</td><td>早期 PoC + 压测，必要时 fallback epoll</td></tr><tr><td>数据一致性</td><td>Hybrid Schema + 异步写 复杂</td><td>DataProxy 写队列 + WAL + 测试</td></tr><tr><td>AOI/Scene 复杂度</td><td>多服务交互，容灾难度大</td><td>明确接口、仿真和压测、容灾演练</td></tr><tr><td>插件/依赖安全</td><td>动态加载风险</td><td>插件签名、沙箱、代码审计</td></tr><tr><td>SDK 生态</td><td>Unity SDK 需要持续维护</td><td>提前开放内测，建立反馈机制</td></tr></tbody></table><h2 id="_5-追踪方式" tabindex="-1"><a class="header-anchor" href="#_5-追踪方式"><span>5. 追踪方式</span></a></h2><ul><li>每个阶段结束进行里程碑评审，输出：设计文档、代码、测试报告。</li><li>Jira/Issue 跟踪任务；CI/CD 状态驱动质量门禁。</li><li>指标（性能、上线质量、故障率）纳入 OKR。</li></ul><hr><p>本实施计划对齐最新架构文档（NetCore、Transport、AOI、DataProxy、API、DevOps、安全等），为未来 12 个月的研发与运营提供执行路线。***</p>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};